import ctypes
import os

# Load the libraries
ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

# Define the function prototype
# double gsl_cdf_gumbel2_Pinv(const double P, const double a, const double b);
gsl.gsl_cdf_gumbel2_Pinv.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double]
gsl.gsl_cdf_gumbel2_Pinv.restype = ctypes.c_double

def gumbel2_pinverse(P, a, b):
    """Compute the inverse CDF for the Gumbel Type-II distribution."""
    if not (0.0 <= P <= 1.0):
        raise ValueError("Probability P must be in the range [0, 1].")
    if a <= 0 or b <= 0:
        raise ValueError("Shape parameter a and scale parameter b must be positive.")
    return gsl.gsl_cdf_gumbel2_Pinv(P, a, b)

def assert_test():
    # Test cases
    try:
        assert abs(gumbel2_pinverse(0.5, 2.0, 3.0) - 2.0) < 1e-6, "Test case 1 failed"
        assert abs(gumbel2_pinverse(0.0, 2.0, 3.0) - 0.0) < 1e-6, "Test case 2 failed"
        assert gumbel2_pinverse(1.0, 2.0, 3.0) == float('inf'), "Test case 3 failed"
        assert abs(gumbel2_pinverse(0.25, 1.0, 1.0) - 0.5) < 1e-6, "Test case 4 failed"
        print("All test cases passed.")
    except AssertionError as e:
        print(e)
    except ValueError as ve:
        print(f"ValueError: {ve}")

if __name__ == "__main__":
    assert_test()
